    "self-hosting.costs.limits.no_mail_label": "Without a mail service:",
    "self-hosting.costs.limits.no_model_body": " sign-in and permissions, manual data table and record management, status flows, background jobs within existing authorization, published public-page reads.",
    "self-hosting.costs.limits.no_model_label": "Works without any model once configured:",
